/// Tail‐recursive (iterative) computation of the triangular number.
/// 
/// Precondition:
///   - `idx <= n`
///   - `*sum == 1 + 2 + … + idx`
///   - the final triangular number `1 + … + n` fits in `u32` (no overflow)
///
/// Postcondition:
///   - `*sum == 1 + 2 + … + n`
pub fn tail_triangle(mut n: u32, mut idx: u32, sum: &mut u32) {
    // As long as the current index is less than the target,
    // bump the index by one and add it into the accumulator.
    while idx < n {
        idx += 1;
        *sum += idx;
    }
}

#[cfg(test)]
mod tests {
    use super::tail_triangle;

    fn brute_triangle(n: u32) -> u32 {
        (1..=n).fold(0, |acc, x| acc + x)
    }

    #[test]
    fn test_tail_triangle() {
        for n in 0..1000 {
            // initialize idx = 0, sum = triangle(0) = 0
            let mut s = 0;
            tail_triangle(n, 0, &mut s);
            assert_eq!(s, brute_triangle(n));

            // test from a nonzero starting index
            if n >= 5 {
                let mut s2 = brute_triangle(5);
                tail_triangle(n, 5, &mut s2);
                assert_eq!(s2, brute_triangle(n));
            }
        }
    }
}